$('#cloud-pending-pairings').onclick=async e=>{const accept=e.target.closest('[data-pair-accept]'),reject=e.target.closest('[data-pair-reject]');if(!accept&&!reject)return;const button=accept||reject,card=button.closest('[data-pair-request]'),request_id=button.dataset.pairAccept||button.dataset.pairReject;const scopes=accept?Array.from(card.querySelectorAll('[data-scope]:checked')).map(x=>x.dataset.scope):[];try{await api('/api/cloud/pairing-decision',{request_id,accept:!!accept,scopes},'POST');toast(accept?'Device pairing approved with selected permissions.':'Pairing request rejected.');await loadCloudStatus()}catch(err){toast(err.message)}};
$('#cloud-device-list').onclick=async e=>{const presence=e.target.closest('[data-pair-presence]');if(presence){const paused=presence.dataset.paused==='1';if(!confirm(paused?'Resume presence for this paired device?':'Pause presence for this paired device? It will remain paired and signaling permissions will be unchanged.'))return;try{await api('/api/cloud/pairing-presence',{device_id:presence.dataset.pairPresence,paused:!paused},'POST');toast(paused?'Device presence resumed.':'Device presence paused.');await loadCloudStatus()}catch(err){toast(err.message)}return}const b=e.target.closest('[data-pair-revoke]');if(!b)return;if(!confirm('Revoke this device pairing?'))return;try{await api('/api/cloud/pairing-revoke',{device_id:b.dataset.pairRevoke},'POST');toast('Device pairing revoked.');await loadCloudStatus()}catch(err){toast(err.message)}};
