async function loadSettings(){try{const d=await api('/api/settings');$('#settings-language').value=d.language;$('#settings-theme').value=d.theme;for(const [k,v] of Object.entries(d.mail||{})){const el=$('#'+k);if(el&&el.type==='checkbox')el.checked=(v==='1'||v===1||v===true);else if(el&&!k.endsWith('_pass'))el.value=v||'';if(el&&k.endsWith('_pass')&&v)el.placeholder='Saved securely · leave blank to keep'}$('#public_base_url').value=d.public_base_url||'';await loadTranslationList()}catch(e){toast(e.message)}}
$('#save-preferences').onclick=async()=>{try{await api('/api/settings/save',{language:$('#settings-language').value,theme:$('#settings-theme').value},'POST');state.theme=$('#settings-theme').value;document.body.classList.toggle('dark',state.theme==='dark');await loadLocale($('#settings-language').value);toast(tr('language_saved'))}catch(e){toast(e.message)}};
$('#language-select').onchange=async()=>{const previous=state.locale;try{const selected=$('#language-select').value;await api('/api/settings/save',{language:selected,theme:state.theme},'POST');await loadLocale(selected);toast(selected==='ar'?'تم تغيير لغة DCP':'DCP language updated')}catch(e){$('#language-select').value=previous;toast('Could not change language: '+e.message)}};$('#settings-language').onchange=async()=>{const previous=state.locale;try{const selected=$('#settings-language').value;await api('/api/settings/save',{language:selected,theme:state.theme},'POST');await loadLocale(selected);toast(selected==='ar'?'تم تغيير لغة DCP':'DCP language updated')}catch(e){$('#settings-language').value=previous;toast('Could not change language: '+e.message)}};
