async function loadMailAiProviders(){if(!state.providers.length)await loadProviders();const sel=$('#mail-ai-provider');sel.innerHTML='';const enabled=state.providers.filter(p=>p.enabled===1||p.enabled===true);enabled.forEach(p=>{const o=document.createElement('option');o.value=p.id;o.textContent=p.name;sel.append(o)});const preferred=localStorage.getItem('dcp-provider')||enabled[0]?.id||'';if(preferred&&enabled.some(p=>p.id===preferred))sel.value=preferred;const selected=enabled.find(p=>p.id===sel.value);$('#mail-ai-model').value=localStorage.getItem('dcp-model-'+sel.value)||selected?.model||'';updateMailSendState()}
