function renderTranslationEntries(){const q=($('#translation-search')?.value||'').trim().toLowerCase();const entries=state.translationEntries.filter(([k,v])=>!q||(k+' '+v).toLowerCase().includes(q));$('#translation-count').textContent=entries.length+' / '+state.translationEntries.length;$('#translation-list').innerHTML=entries.map(([k,v])=>'<button type="button" class="translation-row" data-tkey="'+esc(k)+'"><span class="translation-key">'+esc(k)+'</span><span class="translation-value">'+esc(v)+'</span><span class="translation-edit">Edit</span></button>').join('')||'<div class="empty-state">No translation keys match your search.</div>';$$('[data-tkey]').forEach(b=>b.onclick=()=>{$('#translation-key').value=b.dataset.tkey;$('#translation-value').value=state.translationEntries.find(x=>x[0]===b.dataset.tkey)?.[1]||'';$('#translation-key').focus()})}
